import{_ as a,o as e,c as i,a2 as s}from"./chunks/framework.BUwdTBzS.js";const k=JSON.parse('{"title":"5 分钟快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md","lastUpdated":1787023323000}'),d={name:"guide/quick-start.md"};function l(o,t,n,r,h,c){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="_5-分钟快速上手" tabindex="-1">5 分钟快速上手 <a class="header-anchor" href="#_5-分钟快速上手" aria-label="Permalink to &quot;5 分钟快速上手&quot;">​</a></h1><p>本文帮你在 5 分钟内跑通「安装 → 触发 dev-flow → 完成一次开发」的最小闭环。</p><h2 id="第-1-步-安装-1-分钟" tabindex="-1">第 1 步：安装（1 分钟） <a class="header-anchor" href="#第-1-步-安装-1-分钟" aria-label="Permalink to &quot;第 1 步：安装（1 分钟）&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-repo-ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/ai-coding-kit</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/ai-coding-kit/skills/dev-flow/dist</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre></div><p>安装完成后，<code>~/.codebuddy/</code> 下即拥有 15 个 Skill、2 条核心规则和 10 个 Agents。详见 <a href="/ai-coding-kit/guide/installation">安装与配置</a>。</p><h2 id="第-2-步-触发-dev-flow-1-分钟" tabindex="-1">第 2 步：触发 dev-flow（1 分钟） <a class="header-anchor" href="#第-2-步-触发-dev-flow-1-分钟" aria-label="Permalink to &quot;第 2 步：触发 dev-flow（1 分钟）&quot;">​</a></h2><p>dev-flow <strong>仅由显式命令触发</strong>，AI 不会基于关键词自作主张启动。在对话中输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dev-flow</span></span></code></pre></div><p>或直接带上你的需求：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dev: 给登录页加一个「记住我」勾选框</span></span></code></pre></div><p>也支持轻量模式：</p><table tabindex="0"><thead><tr><th>命令</th><th>适用场景</th></tr></thead><tbody><tr><td><code>dev-flow</code> / <code>dev:</code></td><td>标准流程（阶段 0 + 步骤 1~10）</td></tr><tr><td><code>dev-flow --micro</code></td><td>微改动（≤3 文件、≤10 行/文件、位置明确）</td></tr><tr><td><code>dev-flow --fast</code></td><td>快速模式</td></tr></tbody></table><h2 id="第-3-步-跟随流程-3-分钟" tabindex="-1">第 3 步：跟随流程（3 分钟） <a class="header-anchor" href="#第-3-步-跟随流程-3-分钟" aria-label="Permalink to &quot;第 3 步：跟随流程（3 分钟）&quot;">​</a></h2><p>dev-flow 会引导你走完系统化流程：</p><ol><li><strong>阶段 0 · 需求理解</strong> — 澄清需求，不确定点汇总确认（禁止猜测）。</li><li><strong>步骤 1~3 · 研究分析</strong> — 探索代码、定位影响范围、制定方案。</li><li><strong>步骤 4 · 方案决策</strong> — 智能评估推荐执行深度（标准 / 完整 / 分批）。</li><li><strong>步骤 5 · 编码</strong> — 最小入侵实现，遵守 12 条核心红线。</li><li><strong>步骤 5.5 · 自检</strong> — L1 代码审查 + 文档同步 + ESLint 自检。</li><li><strong>步骤 6~10 · 验证与交付</strong> — 自动化验证、提交信息生成、经验沉淀。</li></ol><blockquote><p>每一步都有门控（gate）保障质量，关键步骤由 <a href="/ai-coding-kit/agents/">step-gate Agent</a> 做完整性审计。</p></blockquote><h2 id="常用命令速查" tabindex="-1">常用命令速查 <a class="header-anchor" href="#常用命令速查" aria-label="Permalink to &quot;常用命令速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>dev:status</code> / <code>dev:st</code></td><td>查看当前流程状态</td></tr><tr><td><code>dev:kb</code> / <code>dev:k</code></td><td>代码知识库操作</td></tr><tr><td><code>dev:metrics</code> / <code>dev:m</code></td><td>查看开发度量</td></tr><tr><td><code>dev:onboard</code> / <code>dev:ob</code></td><td>新人上手引导</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>深入 dev-flow 架构与流程 → <a href="/ai-coding-kit/dev-flow/">dev-flow 旗舰板块</a></li><li>浏览全部能力 → <a href="/ai-coding-kit/skills/">Skills 生态</a></li><li>了解质量红线 → <a href="/ai-coding-kit/rules/">Rules 规范</a></li></ul>`,20)])])}const g=a(d,[["render",l]]);export{k as __pageData,g as default};
